def predict(x):
    if x[0] <= 5:
        if x[1] <= 2:
            return 1
        return 0
    if x[1] <= 4:
        return 0
    return 1

pred_a = predict((4, 3))
pred_b = predict((6, 3))
pred_c = predict((6, 5))
votes = pred_a + pred_b + pred_c
pred = 1 if votes >= 2 else 0
